package dev.thefoolish.generated.makeananimeapplikemihonit;

import android.content.Intent;import android.widget.*;
public final class DetailActivity extends GeneratedScreen { protected void render(){String id=getIntent().getStringExtra("id");String title=getIntent().getStringExtra("title");String summary=getIntent().getStringExtra("summary");int episodes=Math.max(1,getIntent().getIntExtra("episodes",12));body.addView(text(title==null?"Anime detail":title,22,true));body.addView(text(summary==null?"":summary,14,false));Button fav=action(store.flag("fav_"+id)?"Remove favorite":"Add favorite");fav.setOnClickListener(v->{boolean n=!store.flag("fav_"+id);store.flag("fav_"+id,n);fav.setText(n?"Remove favorite":"Add favorite");});body.addView(fav);body.addView(text("Episodes",18,true));for(int e=1;e<=Math.min(episodes,24);e++){final int ep=e;Button play=action("Episode "+e+(store.number("progress_"+id+"_"+e)>0?" · resume":""));play.setOnClickListener(v->{Intent i=new Intent(this,PlayerActivity.class);i.putExtra("id",id);i.putExtra("title",title);i.putExtra("episode",ep);startActivity(i);});body.addView(play);}}}
